/**
 * PathfindingGrid - Defines the walkable area for pathfinding
 *
 * @extends THREE.EventDispatcher
 */
export class PathfindingGrid {
    /**
     * @param {Object} config - Configuration options
     * @param {THREE.Box3} [config.bounds] - World bounds for the navigation grid
     * @param {number} [config.cellSize=1.0] - Size of each grid cell in world units
     * @param {number} [config.agentHeight=1.8] - Height of agents using this grid
     * @param {number} [config.agentRadius=0.5] - Collision radius of agents
     * @param {number} [config.maxSlope=Math.PI/4] - Maximum walkable slope in radians (45 degrees)
     * @param {number} [config.maxStepHeight=0.5] - Maximum step height between cells
     * @param {number} [config.gridBudget=200] - Max cells to generate per physics frame
     * @param {number} [config.maxAgents=128] - Maximum concurrent pathfinding agents
     */
    constructor(config?: {
        bounds?: THREE.Box3;
        cellSize?: number;
        agentHeight?: number;
        agentRadius?: number;
        maxSlope?: number;
        maxStepHeight?: number;
        gridBudget?: number;
        maxAgents?: number;
    });
    /**
     * Three.js-style type flag.
     * @type {boolean}
     */
    isPathfindingGrid: boolean;
    /**
     * World bounds for the navigation grid.
     * @type {THREE.Box3}
     */
    bounds: THREE.Box3;
    /**
     * Size of each grid cell in world units.
     * @type {number}
     */
    cellSize: number;
    /**
     * Height of agents using this grid.
     * @type {number}
     */
    agentHeight: number;
    /**
     * Collision radius of agents.
     * @type {number}
     */
    agentRadius: number;
    /**
     * Maximum walkable slope in radians.
     * @type {number}
     */
    maxSlope: number;
    /**
     * Maximum step height between adjacent cells.
     * @type {number}
     */
    maxStepHeight: number;
    /**
     * Max cells to generate per physics frame.
     * @type {number}
     */
    gridBudget: number;
    /**
     * Maximum concurrent pathfinding agents.
     * @type {number}
     */
    maxAgents: number;
    /**
     * Physics instance reference.
     * @type {Object|null}
     * @private
     */
    private _physics;
    /**
     * Whether the grid has been initialized.
     * @type {boolean}
     * @private
     */
    private _initialized;
    /**
     * Whether the grid has been compiled.
     * @type {boolean}
     * @private
     */
    private _compiled;
    /**
     * Initialize the grid with a Physics instance.
     * Must be called before enabling navigation on any body.
     *
     * @param {Object} physics - Physics instance
     * @returns {Promise<PathfindingGrid>} This instance for chaining
     * @throws {Error} If physics or physicsApi is not available
     */
    init(physics: any): Promise<PathfindingGrid>;
    /**
     * Compile the entire navigation grid.
     * This generates all cells within bounds immediately, rather than lazily.
     * Useful for ensuring pathfinding works immediately without warm-up.
     *
     * @param {Object} [options] - Compilation options
     * @param {number} [options.budget=5000] - Temporary budget for fast generation
     * @returns {Promise<PathfindingGrid>} This instance for chaining
     * @throws {Error} If not initialized
     */
    compile(options?: {
        budget?: number;
    }): Promise<PathfindingGrid>;
    /**
     * Alias for compile (backwards compatibility).
     * @deprecated Use compile() instead
     */
    precompute(options?: {}): Promise<PathfindingGrid>;
    /**
     * Get the current grid data for visualization or debugging.
     *
     * @returns {Promise<Object>} Grid data with cells array
     * @throws {Error} If not initialized
     */
    getGridData(): Promise<any>;
    /**
     * Update configuration. Changes take effect on next pathfinding operation.
     *
     * @param {Object} config - Configuration options (same as constructor)
     * @returns {Promise<PathfindingGrid>} This instance for chaining
     */
    set(config: any): Promise<PathfindingGrid>;
    /**
     * Whether the grid has been initialized.
     * @type {boolean}
     * @readonly
     */
    readonly get initialized(): boolean;
    /**
     * Whether the grid has been compiled.
     * @type {boolean}
     * @readonly
     */
    readonly get compiled(): boolean;
    /**
     * Alias for compiled (backwards compatibility).
     * @type {boolean}
     * @readonly
     * @deprecated Use compiled instead
     */
    readonly get precomputed(): boolean;
    /**
     * Get the physics instance.
     * @type {Object|null}
     * @readonly
     */
    readonly get physics(): any | null;
    /**
     * Dispose of the navigation grid.
     * Releases references but does not clear the worker-side grid.
     */
    dispose(): void;
}
export const NavigationGrid: typeof PathfindingGrid;
